package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.AcrValuesSupportedVO;

class AcrValuesSupportedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of acr values supported of tenant config")
  void test_acr_values_supported_value_holder_assign_plain_value() {
    Object holder = new Object();
    AcrValuesSupportedValueHolder<Object> value = new AcrValuesSupportedValueHolder<>(holder);
    Assertions.assertSame(holder, value.acrValuesSupported("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getAcrValuesSupportedValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAcrValuesSupported().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.acrValuesSupportedNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAcrValuesSupportedValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getAcrValuesSupported().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of acr values supported of tenant config")
  void test_acr_values_supported_value_holder_assign_value_object() {
    Object holder = new Object();
    AcrValuesSupportedValueHolder<Object> value = new AcrValuesSupportedValueHolder<>(holder);
    AcrValuesSupportedVO vo = AcrValuesSupportedVO.from("one");
    Assertions.assertFalse(value.getAcrValuesSupportedValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.acrValuesSupported(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAcrValuesSupportedValue().orElseThrow());
    Assertions.assertSame(holder, value.acrValuesSupported(Optional.empty()));
    Assertions.assertFalse(value.getAcrValuesSupportedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.acrValuesSupported(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAcrValuesSupportedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of acr values supported of tenant config against the original")
  void test_acr_values_supported_value_holder_read() {
    Object holder = new Object();
    AcrValuesSupportedValueHolder<Object> value = new AcrValuesSupportedValueHolder<>(holder);
    AcrValuesSupportedVO vo = AcrValuesSupportedVO.from("one");
    AcrValuesSupportedVO other = AcrValuesSupportedVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getAcrValuesSupportedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAcrValuesSupported(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAcrValuesSupported(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.acrValuesSupported(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAcrValuesSupported(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAcrValuesSupported(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of acr values supported of tenant config")
  void test_acr_values_supported_value_holder_unset() {
    Object holder = new Object();
    AcrValuesSupportedValueHolder<Object> value = new AcrValuesSupportedValueHolder<>(holder);
    AcrValuesSupportedVO vo = AcrValuesSupportedVO.from("one");
    value.acrValuesSupported(vo);
    Assertions.assertSame(holder,
        value.unsetAcrValuesSupportedIfMatches("acrValuesSupported_other"));
    Assertions.assertTrue(value.getAcrValuesSupportedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAcrValuesSupportedIfMatches("acrValuesSupported"));
    Assertions.assertFalse(value.getAcrValuesSupportedValue().isPresent(),
        "The field name must clear the value");
    value.acrValuesSupported(vo);
    Assertions.assertSame(holder, value.unsetAcrValuesSupported());
    Assertions.assertFalse(value.getAcrValuesSupportedValue().isPresent(),
        "Unset must clear the value");
  }
}
